const meta = {
  title: "Primitives/Translation with Wrappers",
  component: TranslationWithWrappers,
  parameters: {
    chromatic: mobileOnlyMode,
    docs: {
      description: {
        component:
          "Renders a translated label where selected `{{placeholder}}`s are wrapped in React elements, e.g. a " +
          "bold name or a link inside a sentence. The label is translated with the interpolation values as " +
          "usual, except that keys with a wrapper are left as placeholders, then each placeholder is replaced by " +
          "the wrapper's output. Placeholders can be named (`{{name}}`, object interpolation) or indexed " +
          "(`{{0}}`, array interpolation).",
      },
    },
  },
  args: {
    label: "CUSTOM_LABEL_WITH_STRING_PLACEHOLDERS" as LabelKey,
    interpolation: { name: "Andreas" },
    wrappers: { name: (s) => <b>{s}</b> },
  },
} satisfies Meta<typeof TranslationWithWrappers>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const wrapped = canvas.getByText("Andreas");
    await expect(wrapped.tagName).toBe("B");
    await expect(canvasElement).toHaveTextContent("Hej, mitt namn är Andreas. Slit inte ut det!");
  },
};

export const VariantPlaceholders: Story = {
  parameters: showcaseParameters,
  render: function StoryComponent() {
    const { t } = useTranslation();
    return (
      <ShowcaseLayout title="Placeholder kinds (named, indexed, several, link)" variantType="other">
        <Variant label="named placeholder, object interpolation">
          <p>
            <TranslationWithWrappers
              label={"CUSTOM_LABEL_WITH_STRING_PLACEHOLDERS" as LabelKey}
              interpolation={{ name: "Andreas" }}
              wrappers={{ name: (s) => <b>{s}</b> }}
            />
          </p>
        </Variant>
        <Variant label="indexed placeholder, array interpolation">
          <p>
            <TranslationWithWrappers
              label={"CUSTOM_LABEL_WITH_ARRAY_PLACEHOLDERS" as LabelKey}
              interpolation={["Andreas"]}
              wrappers={{ 0: (s) => <b>{s}</b> }}
            />
          </p>
        </Variant>
        <Variant label="several placeholders, only one wrapped">
          <p>
            <TranslationWithWrappers
              label={"CUSTOM_LABEL_WITH_MULTI_ARRAY_PLACEHOLDERS" as LabelKey}
              interpolation={["Carl Gustaf", "Ers Höghet Kungen", "75"] as const}
              wrappers={{ 1: (s) => <b style={{ color: "purple" }}>{s}</b> }}
            />
          </p>
        </Variant>
        <Variant label="link inside the sentence">
          <p>
            <TranslationWithWrappers
              label={"CUSTOM_LABEL_WITH_LINK" as LabelKey}
              interpolation={{ 0: t("CUSTOM_LABEL_WITH_LINK_LINK_CONTENT" as LabelKey) }}
              wrappers={{ 0: (s) => <a href="https://www.parksandresorts.com">{s}</a> }}
            />
          </p>
        </Variant>
      </ShowcaseLayout>
    );
  },
};
